     test('AC1: every primary upload step carries an id the retry references',
         () {
       for (final step in primaries) {
         expect(
           step['id'],
           isA<String>(),
           reason:
               'primary upload step "${step['name'] ?? step['uses']}" '
               'lost its id — the gh-1412 retry keys on steps.<id>.outcome',
         );
       }
     });

     test('AC2: each primary upload is followed by an overwrite:true retry',
         () {
       for (var i = 0; i < steps.length; i++) {
         final step = steps[i];
         if (!isUploadStep(step) || isRetryStep(step)) continue;
         final id = step['id'] as String;
         expect(i + 1, lessThan(steps.length),
             reason: 'primary upload "$id" has no retry step after it');
         final retry = steps[i + 1];
         expect(
           isUploadStep(retry) && isRetryStep(retry),
           isTrue,
           reason:
               'the step after primary upload "$id" must be its gh-1412 '
               'retry (an upload-artifact step keyed on '
               "steps.$id.outcome == 'failure')",
         );
         expect(
           retry['uses'],
           artifactPin,
           reason:
               'the retry of "$id" must ride the same digest-validating '
               'upload-artifact line (gh-995 pin, release_hygiene_test.dart)',
         );
         expect(
           retry['if']?.toString(),
           contains("steps.$id.outcome == 'failure'"),
           reason: 'the retry of "$id" must fire only on the failed upload',
         );
         expect(
           (retry['with'] as YamlMap)['overwrite'],
           true,
           reason:
               'the retry of "$id" must overwrite the half-registered '
               'artifact a finalize-class failure leaves behind — with the '
               'default overwrite:false the retry dies on "already exists"',
         );
         expect(
           (retry['with'] as YamlMap)['name'],
           (step['with'] as YamlMap)['name'],
           reason:
               'the retry of "$id" must re-upload the SAME artifact name '
               'the coverage merge / rebalancer downloads',
         );
         expect(
           (retry['with'] as YamlMap)['path'],
           (step['with'] as YamlMap)['path'],
           reason:
               'the retry of "$id" must re-upload the SAME path the '
               'coverage merge / rebalancer reads — a drifted path would '
               'upload wrong/empty content under the correct artifact name',
         );
         expect(
           (retry['with'] as YamlMap)['retention-days'],
           (step['with'] as YamlMap)['retention-days'],
           reason:
               'the retry of "$id" must keep the SAME retention-days — '
               'a re-upload that outlives or dies before the window its '
               'consumer expects silently shifts the evidence contract',
         );
       }
     });

     test('AC3: retries stay always()-reachable and never continue-on-error',
         () {
       for (final retry in retries) {
         expect(
           retry['if']?.toString(),
           contains('always()'),
           reason:
               'the gh-1724 retries must stay reachable after a failed '
               'upload step — without always() GitHub skips every later '
               'step of a failing job and the retry would never fire',
         );
         expect(
           retry['continue-on-error'],
           isNot(true),
           reason:
               'a genuinely dead blob endpoint must still fail the shard '
               'loudly — the merge gates assert on these artifacts',
         );
       }
     });

     test('AC4: the job-level gate still scopes every upload (incl. retries)',
         () {
       final jobIf = job(jobId)['if']?.toString() ?? '';
       expect(
         jobIf,
         contains(scope),
         reason:
             '$jobId uploads (primaries and retries) are scoped by the '
             'job-level gate — the retries must never run outside it',
       );
       expect(
         jobIf,
         contains("needs.release-pending.outputs.pending == 'true'"),
         reason:
             '$jobId is a release leg — the pending gate must scope its '
             'evidence uploads',
       );
     });

     test('the merge gate still hard-counts the shard reports', () {
       // The retries exist so this count can't be poisoned by a transient
       // finalize failure — the gate itself must stay strict.
       final expected = shardCount(jobId);
       expect(expected, primaryCount == 2 ? 3 : 2, ...);
     });
   });
 }
``

